  ('chg:profiles: columns signed-in users can read', 'CHANGE', array['m04']::text[], false, 'migration 4: signed-in users can no longer read status_reason / status_changed_* directly'),
  ('chg:profiles: columns anonymous visitors can read', 'CHANGE', array['m04']::text[], true, 'migration 4: anonymous visitors lose the profiles table privilege (no change is fine if they had none)'),
  ('keep:profiles: write privileges of signed-in users', 'SAME', array[]::text[], false, 'profiles INSERT / UPDATE / DELETE privileges are untouched'),
  ('keep:profiles: privileges held by roles other than anon and authenticated', 'SAME', array[]::text[], false, 'profiles privileges of every other role are untouched'),
