  ('keep:inv_reference_counters: columns, policies and privileges', 'SAME', array[]::text[], false, 'inv_reference_counters columns, policies and privileges are untouched'),
  ('keep:the existing counters (unit, stock, request, transfer, movement, count) are not touched', 'SAME', array[]::text[], false, 'existing reference counters are untouched'),
  ('keep:companies with the dispatch-note switch ON (must be 0)', 'SAME', array[]::text[], false, 'the dispatch / return notes switch stays OFF for every company'),
  ('keep:scheduler: pg_cron job definitions (cron.job)', 'SAME', array[]::text[], false, 'scheduled jobs are untouched (pg_cron job definitions)'),
  ('keep:installed extensions', 'SAME', array[]::text[], false, 'no extension was added, removed or upgraded')
),
now_items as (select item, case when item like 'rows:%' and value ~ '^[0-9]+:' then split_part(value, ':', 1) || ':' || left(split_part(value, ':', 2), 16) when length(value) <= 16 then value else left(md5(value), 16) end as value, value as full_value, ok from cur),
pending as (select m as mig from unnest(array['m01', 'm02', 'm03', 'm04', 'm05', 'm06', 'm07', 'm08', 'm09', 'm10', 'm11', 'm12', 'm13', 'm14']) m where coalesce((select value from before where item = 'pre:' || m), 'absent') = 'absent'),
cmp as (
  select e.item, e.kind, e.migs, e.same_ok, e.what, b.value as before_value, c.value as now_value, c.full_value, c.ok,
    case when b.item is null then 'MISSING IN DIGEST' when c.item is null then 'NOT COMPUTED' when b.value = c.value then 'SAME'
         when b.value = 'ABSENT' and c.value <> 'ABSENT' then 'ADDED' when c.value = 'ABSENT' then 'REMOVED' else 'CHANGED' end as obs,
    exists (select 1 from pending p where p.mig = any (e.migs)) as pending
  from expect e left join before b on b.item = e.item left join now_items c on c.item = e.item
),
classified as (
  select cmp.*,
    case
      when obs in ('MISSING IN DIGEST', 'NOT COMPUTED') then 'UNEXPECTED'
      when kind = 'SAME' then case when obs = 'SAME' and coalesce(ok, true) then 'PRESERVED' else 'UNEXPECTED' end
      when pending then case when obs in ('CHANGED', 'ADDED') and coalesce(ok, true) then 'INTENDED'
                             when obs = 'SAME' and same_ok and coalesce(ok, false) then 'PRESERVED' else 'UNEXPECTED' end
      else case when obs = 'SAME' and coalesce(ok, true) then 'PRESERVED' else 'UNEXPECTED' end
    end as verdict
  from cmp
),
ver as (
  select 'base' as pack, grp, chk, item, result, detail from (
with eight(name) as (values ('crm_grant_access'), ('crm_revoke_access'), ('proj_grant_access'), ('proj_revoke_access'), ('inv_grant_access'), ('inv_revoke_access'), ('pbx_grant_access'), ('pbx_revoke_access')),
tables(name) as (values ('crm_company_grants'), ('proj_company_grants'), ('inv_company_grants'), ('pbx_company_grants')),
fn as (select p.oid, p.proname, p.prosrc, p.prosecdef, p.proconfig from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in (select name from eight)),
-- text that must be present in each function: the new rule (N) or an earlier protection that must survive (E)
needs(fname, kind, label, needle) as (values
  ('pbx_grant_access', 'N', 'R1: only an approver gives or removes the approver right', 'Only a CEO / CTO approver of this company can give or remove the approver right'),
